selector_to_html = {"a[href=\"#commit-scopes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Commit Scopes<a class=\"headerlink\" href=\"#commit-scopes\" title=\"Link to this heading\">#</a></h2><p>An atomic commit can alter multiple files.  For example, an interface\nchange would require modifications the class definitions, method\ncalls, and property references throughout the codebase.  Per\n<em>Conventional Commits</em>, a commit scope is an <strong>OPTIONAL</strong>\nabbreviation, acronym, codename, or keyword that provides additional\ncontext to reviewers by naming the essential component of the change.</p><p>For Python code changes, the commit scope <strong>SHOULD</strong> specify the\nsecond-level Python module name of the code instigating the change.\nThe commit scope <strong>MUST NOT</strong> include the module\u2019s top-level prefix or\nany suffixes.  Functional/unit test changes <strong>SHOULD</strong> reference the\nscope of the code being exercised, while changes to integration tests\n<strong>MUST NOT</strong> specify a scope.</p>", "a[href=\"#code-style\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Code Style<a class=\"headerlink\" href=\"#code-style\" title=\"Link to this heading\">#</a></h2><p>This project follows these code styles:</p>", "a[href=\"#term-docs\"]": "<dt id=\"term-docs\"><code class=\"docutils literal notranslate\"><span class=\"pre\">docs</span></code></dt><dd><p>a documentation-only change, including edits to in-line\ndocumentation and comments</p></dd>", "a[href=\"#term-feat\"]": "<dt id=\"term-feat\"><code class=\"docutils literal notranslate\"><span class=\"pre\">feat</span></code></dt><dd><p>a new feature</p></dd>", "a[href=\"#term-chore\"]": "<dt id=\"term-chore\"><code class=\"docutils literal notranslate\"><span class=\"pre\">chore</span></code></dt><dd><p>a miscellaneous tooling or tool configuration change, e.g., the\n.gitignore file, or a change not covered by the other commit types</p></dd>", "a[href=\"#term-perf\"]": "<dt id=\"term-perf\"><code class=\"docutils literal notranslate\"><span class=\"pre\">perf</span></code></dt><dd><p>a code change that improves performance</p></dd>", "a[href=\"#term-fix\"]": "<dt id=\"term-fix\"><code class=\"docutils literal notranslate\"><span class=\"pre\">fix</span></code></dt><dd><p>a bug fix</p></dd>", "a[href=\"#term-build\"]": "<dt id=\"term-build\"><code class=\"docutils literal notranslate\"><span class=\"pre\">build</span></code></dt><dd><p>a change to the build system or external dependencies, e.g., the\nmakefile</p></dd>", "a[href=\"#term-style\"]": "<dt id=\"term-style\"><code class=\"docutils literal notranslate\"><span class=\"pre\">style</span></code></dt><dd><p>a change that only affects formatting, or a change related to the\nlinter configuration</p></dd>", "a[href=\"#term-refactor\"]": "<dt id=\"term-refactor\"><code class=\"docutils literal notranslate\"><span class=\"pre\">refactor</span></code></dt><dd><p>a code change that neither fixes a bug nor adds a feature</p></dd>", "a[href=\"#term-test\"]": "<dt id=\"term-test\"><code class=\"docutils literal notranslate\"><span class=\"pre\">test</span></code></dt><dd><p>a new test or a correction to an existing test</p></dd>", "a[href=\"#commit-messages\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Commit Messages<a class=\"headerlink\" href=\"#commit-messages\" title=\"Link to this heading\">#</a></h2><p>This project implements\n<a class=\"reference external\" href=\"https://semver.org/spec/v2.0.0.html\">Semantic Versioning 2.0.0</a> using\n<a class=\"reference external\" href=\"https://www.conventionalcommits.org/en/v1.0.0/\">Conventional Commits 1.0.0</a>:</p>", "a[href=\"#term-ci\"]": "<dt id=\"term-ci\"><code class=\"docutils literal notranslate\"><span class=\"pre\">ci</span></code></dt><dd><p>a change to continuous integration/continuous delivery (CI/CD)\nprocesses, e.g., GitHub Actions</p></dd>", "a[href=\"#contribution-guidelines\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Contribution Guidelines<a class=\"headerlink\" href=\"#contribution-guidelines\" title=\"Link to this heading\">#</a></h1><p>The project practices <a class=\"reference external\" href=\"https://tdd.mooc.fi/\">test-driven development</a>\nin\n<a class=\"reference external\" href=\"https://www.atlassian.com/git/tutorials/comparing-workflows/feature-branch-workflow\">Git feature (topic) branches</a>\nto maintain a <a class=\"reference external\" href=\"https://archive.is/VpWTs\">linear commit history</a>.\nChanges must be self-contained and buildable, with updated tests and\ndocumentation.  Please rebase changes on the latest HEAD of the main\nbranch before submitting them for review as a\n<a class=\"reference external\" href=\"https://docs.github.com/en/pull-requests/collaborating-with-pull-requests\">GitHub pull request</a>.</p>", "a[href=\"#commit-types\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Commit Types<a class=\"headerlink\" href=\"#commit-types\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#development-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Development Environment<a class=\"headerlink\" href=\"#development-environment\" title=\"Link to this heading\">#</a></h2><p>This project requires Python 3.12 (or newer).  To set up your\ndevelopment environment on Linux or macOS, run these\n<a class=\"reference external\" href=\"https://www.gnu.org/software/make/\">GNU Make</a> commands from the\nproject root directory.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
